/**
 * @file mapping.hpp
 * @brief Translation of plant messages into the twin's data contract (pure, no I/O).
 * @ingroup ingest
 *
 * A plant message is a JSON document (REST body, or MQTT payload parsed as JSON) or a scalar
 * (an MQTT payload such as "71.5" on a per-tag topic). The mapping, generated by Studio from
 * the instance's bindings and the Blueprint's data contract, says:
 *  - **telemetry**: which field, JSON path or MQTT topic carries each signal, and the key the
 *    runtime's telemetry stream uses for it (the binding's selected field — the key the
 *    instance's telemetry channels listen to). Values are converted to the signal's declared
 *    type (numbers and booleans may arrive as text); anything else is a reported problem,
 *    never a silent coercion. Unit scale/offset is applied later, by Studio, as for every
 *    runtime channel;
 *  - **events**: which event of the contract a field value or a topic raises, giving the
 *    event's PT label (the Physical Twin's vocabulary, translated by the verified label
 *    equivalence inside the runtime);
 *  - **timestamp**: the field carrying the plant's own time (epoch milliseconds or seconds, or
 *    an ISO 8601 string), or none (arrival time is used).
 *
 * The twin's own vocabulary always works as well: a field named after a telemetry id, and an
 * event field (default "event") holding an event id or a PT label. Codes that match nothing
 * are reported as unmapped and are never sent. The mapping decides nothing about the twin's
 * state: the runtime's kernel accepts or rejects each event.
 */
#pragma once

#include <optional>
#include <string>
#include <string_view>
#include <vector>

#include "twin/core/result.hpp"
#include "twin/json/canonical.hpp"

namespace twin::ingest {

/// @brief Where a value is read from: a top-level field, a JSON path ("$.a.b[0]") or an MQTT topic filter.
struct Selector {
    std::string field;  ///< Top-level field name.
    std::string path;   ///< JSON path ("$.a.b" or "a.b[1].c").
    std::string topic;  ///< MQTT topic filter (+ and # allowed); the payload, or field/path inside it.
};

/// @brief One telemetry signal of the contract.
struct TelemetryRule {
    std::string id;           ///< Telemetry id of the data contract.
    std::string key;          ///< Key forwarded to the runtime (what the instance's channel listens to).
    std::string type{"real"}; ///< real, integer, boolean, string or enum.
    Selector select;          ///< Where the plant sends it (may be empty: the id itself).
};

/// @brief One event of the contract that the plant can raise.
struct EventRule {
    std::string id;                    ///< Event id of the data contract.
    std::string pt;                    ///< Its PT label (e.g. "start_cmd!").
    Selector select;                   ///< Where it is signalled (empty: the event field only).
    std::optional<std::string> value;  ///< The value that raises it (e.g. "START"); none: any true value.
};

/// @brief Where the plant's own time is.
struct TimestampRule {
    std::string field;          ///< Field or JSON path; empty: arrival time.
    std::string unit{"ms"};     ///< ms or s (numbers since the epoch), or iso8601 (strings).
};

/// @brief The whole mapping of one instance.
struct Mapping {
    std::vector<TelemetryRule> telemetry;  ///< Signals.
    std::vector<EventRule> events;         ///< Events with a PT label.
    std::string event_field{"event"};      ///< Field holding event codes, ids or PT labels.
    TimestampRule timestamp;               ///< Plant time.
};

/// @brief What one message contains, in the twin's vocabulary.
struct Translation {
    json::Json telemetry = json::Json::object();  ///< key -> typed value.
    std::vector<std::string> events;              ///< PT labels, in message order.
    std::optional<double> source_seconds;         ///< Plant timestamp (seconds since its epoch).
    std::vector<std::string> unmapped;            ///< Event codes that match no event.
    std::vector<std::string> problems;            ///< Values of the wrong type, malformed timestamps, ...
};

/// @brief Parse a mapping document ({telemetry[], events[], eventField, timestamp}).
[[nodiscard]] Result<Mapping> mapping_from_json(const json::Json& doc);
/// @brief The mapping document of @p m (inverse of mapping_from_json).
[[nodiscard]] json::Json to_json(const Mapping& m);

/// @brief An MQTT payload as a JSON value: parsed when it is JSON, otherwise the text itself.
[[nodiscard]] json::Json decode_payload(std::string_view payload);

/// @brief Value at a top-level field or JSON path ("$.a.b[0].c", "a.b"); nullptr when absent.
[[nodiscard]] const json::Json* select_path(const json::Json& doc, std::string_view path);

/// @brief Seconds since the epoch of a timestamp value in @p unit (ms, s, iso8601); none if malformed.
[[nodiscard]] std::optional<double> timestamp_seconds(const json::Json& value, std::string_view unit);

/// @brief Translate one message received on @p topic ("" for REST).
[[nodiscard]] Translation translate(const Mapping& mapping, const json::Json& message, std::string_view topic);

}  // namespace twin::ingest
